SELECT jsonb_build_object('guildId',guild_id::text,'kind',kind,'channelId',channel_id::text, 'enabled',enabled,'cursorEventId',cursor_event_id::text,'dateCreated',to_char(date_created AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'dateUpdated',to_char(date_updated AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')) AS value FROM zc_private.discord_guild_feed WHERE enabled=true ORDER BY guild_id,kind
